    "_id": "post-1",
    "title": "VIT Vellore vs BITS Pilani Dual Degree: Is the higher fee worth it?",
    "content": "Got 89% in BITSAT (likely getting MSc Economics or MSc Physics dual degree) and Category 1 CSE at VIT Vellore. Family can manage the BITS fee with an education loan of ~15 Lakhs. My main concern is whether the BITS dual degree workload is manageable to get CSE in year 2, vs the safety of confirmed CSE Category 1 at VIT Vellore. Looking for seniors from both universities to weigh in on ROI, peer group, and freedom/culture.",
    "postType": "question",
    "flair": "Ask Campus",
    "collegeName": "Birla Institute of Technology and Science, Pilani",
    "authorName": "Aditya Gupta",
    "authorPseudonym": "u/BitsAspirant_25",
    "authorCollege": "JEE Aspirant",
    "isVerifiedStudent": false,
    "tags": [
      "bits-pilani",
      "vit-vellore",
      "fees",
      "dual-degree",
      "roi"
    ],
    "upvoteCount": 98,
